theorem reachable_maps {C A : Type}
    {concrete : TransitionSystem C}
    {abstract : TransitionSystem A}
    (r : Refinement concrete abstract) :
    ∀ {c}, Reachable concrete c →
      Reachable abstract (r.mapState c)

theorem safety_preserved {C A : Type}
    {concrete : TransitionSystem C}
    {abstract : TransitionSystem A}
    (r : Refinement concrete abstract)
    (safe : A → Prop)
    (hSafe : ∀ a, Reachable abstract a → safe a)
    (c : C)
    (hc : Reachable concrete c) :
    safe (r.mapState c)
